{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table eggozdb.maplemonk.Pri_Sec_table as WITH primary_table AS ( SELECT ROW_NUMBER() OVER (ORDER BY DATE) AS rn, DATE, RETAILER_NAME, AREA_CLASSIFICATION, CASE WHEN area_classification = \'Bangalore-GT\' THEN \'BLR\' WHEN area_classification = \'Hyderabad-GT\' THEN \'HYD\' ELSE \'NCR\' END AS Area, PRODUCT_TYPE, CASE WHEN UPPER(TRIM(product_type)) = \'EVERYDAY\' THEN \'Everyday\' ELSE \'Nutrition\' END AS Product, RETAILER_CATEGORY, RETAILER_TYPE, DISTRIBUTOR, REVENUE, EGGS_SOLD, EGGS_REPLACED, EGGS_RETURN, SALE_TYPE FROM primary_and_secondary_sku WHERE lower(RETAILER_TYPE) in (\'distributor\') and date >= \'2025-04-01\' ), Projected_Revenue AS ( SELECT Area, Product, DATE_TRUNC(\'month\', date) AS month_start, SUM(Revenue) AS MTD, MAX(DAY(date)) AS days_elapsed, DAY(LAST_DAY(DATE_TRUNC(\'month\', date))) AS total_days_in_month, ROUND( SUM(Revenue) * ( DAY(LAST_DAY(DATE_TRUNC(\'month\', date))) / NULLIF(MAX(DAY(date)), 0) ), 2 ) AS Trajectory FROM primary_table WHERE DATE_TRUNC(\'month\', date) = DATE_TRUNC(\'month\', CURRENT_DATE) GROUP BY Area, Product, DATE_TRUNC(\'month\', date)) Select Primary_table.*, bi__target_gt.amount,Projected_revenue.Trajectory from Primary_table Left join PROJECTED_REVENUE on primary_table.area = Projected_revenue.area and primary_table.product = Projected_revenue.Product AND DATE_TRUNC(\'month\', Primary_table.date) = Projected_Revenue.month_start left join bi__target_gt on DATE_TRUNC(\'month\', primary_table.date) = DATE_TRUNC(\'month\', BI__target_gt.Formatted_date) AND Primary_table.Area = Bi__target_gt.area AND UPPER(Primary_table.Product) = UPPER(BI__target_gt.parameter); CREATE OR REPLACE TABLE Sale_productivity_OFFMT AS WITH ps_OFFMT AS ( SELECT pss.*, ROUND(pss.REVENUE / 100000, 2) AS Adj_Revenue, TO_DATE(pss.date) AS clean_date FROM primary_and_secondary_sku pss WHERE LOWER(pss.area_classification) LIKE \'%of-mt%\' AND pss.REVENUE IS NOT NULL AND pss.date >= \'2025-04-01\' ), mtd_calc AS ( SELECT DATE_TRUNC(\'month\', clean_date) AS month_start, SUM(Adj_Revenue) AS actual_mtd, MAX(DAY(clean_date)) AS days_elapsed, DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) AS total_days_in_month, ROUND( SUM(Adj_Revenue) * ( DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) / NULLIF(MAX(DAY(clean_date)), 0) ), 2 ) AS projected_mtd FROM ps_OFFMT WHERE DATE_TRUNC(\'month\', clean_date) = DATE_TRUNC(\'month\', CURRENT_DATE) GROUP BY DATE_TRUNC(\'month\', clean_date) ), target_ofmt AS ( SELECT * FROM bi__target_gt WHERE LOWER(type) LIKE \'%mt%\' ) SELECT ps_OFFMT.*, tg.date AS target_date, tg.area, tg.type, tg.amount, tg.amount_in_lakhs, tg.parameter, mtd_calc.actual_mtd, mtd_calc.projected_mtd FROM ps_OFFMT LEFT JOIN target_ofmt tg ON DATE_TRUNC(\'month\', ps_OFFMT.clean_date) = DATE_TRUNC(\'month\', tg.clean_date) LEFT JOIN mtd_calc ON DATE_TRUNC(\'month\', ps_OFFMT.clean_date) = mtd_calc.month_start; CREATE OR REPLACE TABLE Tertiary_sales_Productivity_GT as SELECT * from tertiary_sales ts left join bi_tertiary bt on bt.dsr=ts.SALESPERSON_NAME where ts.status = \'created\' ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            